        coords = [(0.0, 0.0)] * n

    n = len(coords)
    if demands is None:
        demands = [0] + [1] * (n - 1)
    else:
        demands = list(demands) + [0] * max(0, n - len(demands))
    if depot < 0 or depot >= n:
        depot = 0
    if capacity is None:
        capacity = sum(demands)

    cust = [i for i in range(n) if i != depot]

    def dist(a, b):
        ax, ay = coords[a]
        bx, by = coords[b]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    def rload(r):
        s = 0
        for c in r:
            s += demands[c]
        return s

    def rcost(r):
        if not r:
            return 0.0
        c = dist(depot, r[0])
        for i in range(len(r) - 1):
            c += dist(r[i], r[i + 1])
        return c + dist(r[-1], depot)

    def best_insert(r, node):
        if r:
            best_p = 0
            best_d = dist(depot, node) + dist(node, r[0]) - dist(depot, r[0])
            for p in range(1, len(r)):
                d = dist(r[p - 1], node) + dist(node, r[p]) - dist(r[p - 1], r[p])
                if d < best_d - 1e-12 or (abs(d - best_d) <= 1e-12 and p < best_p):
                    best_d, best_p = d, p
            d = dist(r[-1], node) + dist(node, depot) - dist(r[-1], depot)
            if d < best_d - 1e-12 or (abs(d - best_d) <= 1e-12 and len(r) < best_p):
                best_d, best_p = d, len(r)
            return best_p, best_d
        return 0, 2.0 * dist(depot, node)

    def add_node(r, node):
        p, _ = best_insert(r, node)
        return r[:p] + [node] + r[p:]

    un = sorted(cust, key=lambda i: (-demands[i], -dist(depot, i), i))
    routes = []
    while un:
        seed = un.pop(0)
        r = [seed]
        changed = True
        while changed:
            changed = False
            best = None
            for node in un:
                if rload(r) + demands[node] > capacity:
                    continue
                p, d = best_insert(r, node)
                key = (d, -demands[node], dist(depot, node), node)
                if best is None or key < best[0]:
                    best = (key, node, p)
            if best is not None:
                node = best[1]
                r = r[:best[2]] + [node] + r[best[2]:]
                un.remove(node)
                changed = True
        routes.append(r)

    seen = set()
    for r in routes:
        for c in r:
            seen.add(c)
    for node in cust:
        if node not in seen:
            placed = False
            best = None
            for i, r in enumerate(routes):
                if rload(r) + demands[node] > capacity:
                    continue
                p, d = best_insert(r, node)
                key = (d, i, p)
                if best is None or key < best[0]:
                    best = (key, i, p)
            if best is None:
                routes.append([node])
            else:
                i, p = best[1], best[2]
                routes[i] = routes[i][:p] + [node] + routes[i][p:]

    improved = True
    steps = 0
    while improved and steps < 120:
        steps += 1
        improved = False
        for i in range(len(routes)):
            r1 = routes[i]
            c1 = rcost(r1)
            for a in range(len(r1)):
                x = r1[a]
                r1m = r1[:a] + r1[a + 1:]
                c1m = rcost(r1m)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if rload(r2) + demands[x] > capacity:
                        continue
                    for p in range(len(r2) + 1):
                        r2n = r2[:p] + [x] + r2[p:]
                        gain = c1 + rcost(r2) - c1m - rcost(r2n)
                        if gain > 1e-12:
                            routes[i] = r1m
                            routes[j] = r2n
                            if not routes[i]:
                                routes.pop(i)
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break
        if improved:
            continue
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                r1, r2 = routes[i], routes[j]
                l1, l2 = rload(r1), rload(r2)
                c1, c2 = rcost(r1), rcost(r2)
                for a in range(len(r1)):
                    x = r1[a]
                    for b in range(len(r2)):
                        y = r2[b]
                        n1 = l1 - demands[x] + demands[y]
                        n2 = l2 - demands[y] + demands[x]
                        if n1 > capacity or n2 > capacity:
                            continue
                        s1 = r1[:a] + [y] + r1[a + 1:]
                        s2 = r2[:b] + [x] + r2[b + 1:]
                        if c1 + c2 - rcost(s1) - rcost(s2) > 1e-12:
                            routes[i], routes[j] = s1, s2
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break

    out = []
    seen = set()
    for r in routes:
        rr = []
        for c in r:
            if c != depot and c not in seen:
                rr.append(c)
                seen.add(c)
        if rr:
            out.append(rr)
    for node in cust:
        if node not in seen:
            best = None
            for i, r in enumerate(out):
                if rload(r) + demands[node] > capacity:
                    continue
                p, d = best_insert(r, node)
                key = (d, i, p)
                if best is None or key < best[0]:
                    best = (key, i, p)
            if best is None:
                out.append([node])
            else:
                i, p = best[1], best[2]
                out[i] = out[i][:p] + [node] + out[i][p:]
    return out
